            self.personality_states['formality'] = min(1.0, self.personality_states['formality'] + 0.1)
        else:
            self.personality_states['formality'] = max(0.0, self.personality_states['formality']  0.05)

        if any(kw in message_lower for kw in humor_keywords):
            self.personality_states['humor'] = min(1.0, self.personality_states['humor'] + 0.1)
        else:
            self.personality_states['humor'] = max(0.0, self.personality_states['humor']  0.05)

        if any(kw in message_lower for kw in technical_keywords):
            self.personality_states['technicality'] = min(1.0, self.personality_states['technicality'] + 0.1)
        else:
            self.personality_states['technicality'] = max(0.0, self.personality_states['technicality']  0.05)

        if any(kw in message_lower for kw in empathy_keywords):
            self.personality_states['empathy'] = min(1.0, self.personality_states['empathy'] + 0.1)
        else:
            self.personality_states['empathy'] = max(0.0, self.personality_states['empathy']  0.05)

        if len(user_message) > 200:
            self.personality_states['verbosity'] = min(1.0, self.personality_states['verbosity'] + 0.1)
        else:
            self.personality_states['verbosity'] = max(0.0, self.personality_states['verbosity']  0.05)

        return self.personality_states.copy()

    def generate_system_prompt(self) > str:
        formality = "formális" if self.personality_states['formality'] > 0.6 else "barátságos"
        verbosity = "részletes" if self.personality_states['verbosity'] > 0.6 else "tömör"
