    async def generate_uncertainty_map(self, query: str, response: str) > Dict[str, Any]:
        prompt = f"""Elemezd ezt a választ és add meg a bizonytalansági szinteket minden állításhoz.

Kérdés: {query}
Válasz: {response}

Add vissza JSON formátumban:
{{
    "overall_confidence": 0.01.0,
    "uncertainty_points": [
        {{"statement": "...", "confidence": 0.01.0, "risk_factors": ["..."]}},
    ],
    "alternative_interpretations": ["..."],
    "missing_information": ["..."]
}}"""

        try:
            result = await self.client.chat.completions.create(
                model="gptoss120b",
                messages=[
                    {"role": "system", "content": "Te egy uncertainty analysis expert vagy. JSON formátumban válaszolj."},
                    {"role": "user", "content": prompt}
                ],
                temperature=0.3,
                max_tokens=2000
            )

            content = result.choices[0].message.content
            return json.loads(content)
        except Exception as e:
            return {
                "overall_confidence": 0.5,
                "error": str(e),
                "uncertainty_points": [],
                "alternative_interpretations": [],
                "missing_information": []
            }

    async def generate_reasoning_chain(self, query: str, steps: int = 5) > List[ReasoningChain]:
        chains = []

        for i in range(steps):
            previous_steps = '\n'.join([c.reasoning for c in chains])
            prompt = f"""Lépés {i+1}/{steps}  Gondolkodj végig ezen a kérdésen:
{query}

Előző lépések:
{previous_steps}

Add meg a következő gondolati lépést és a bizonyosság szintjét."""

            response = await self.client.chat.completions.create(
                model="gptoss120b",
                messages=[{"role": "user", "content": prompt}],
                temperature=0.7,
                max_tokens=500
            )

            content = response.choices[0].message.content

            chains.append(ReasoningChain(
                step=i+1,
                model="gptoss120b",
                reasoning=content,
                confidence=0.7 + (np.random.random()  0.3),
                uncertainty_map={
                    "factual_accuracy": np.random.random(),
                    "logical_consistency": np.random.random(),
                    "completeness": np.random.random()
                },
                timestamp=datetime.now().isoformat()
            ))

        return chains

class MultiModelDebateArena:
    def __init__(self, cerebras_api_key: str):
        self.client = AsyncCerebras(api_key=cerebras_api_key)
        self.models = ["gptoss120b", "llama3.370b", "qwen332b"]

    async def conduct_debate(self, topic: str, rounds: int = 3) > Dict[str, Any]:
        participants = []
        debate_log = []

        for model in self.models:
            response = await self.client.chat.completions.create(
                model=model,
                messages=[
                    {"role": "system", "content": f"Te a {model} vagy egy vitában. Érvelj meggyőzően."},
                    {"role": "user", "content": f"Téma: {topic}\n\nMi a véleményed és miért?"}
                ],
                temperature=0.8,
                max_tokens=800
            )

            position = response.choices[0].message.content

            participant = DebateParticipant(
                model_name=model,
                position=position,
                arguments=[position],
                confidence=0.8
            )
            participants.append(participant)
            debate_log.append({
                "round": 1,
                "model": model,
                "statement": position
            })

        for round_num in range(2, rounds + 1):
            for i, participant in enumerate(participants):
                other_positions = [p.position for j, p in enumerate(participants) if j != i]

                counter_prompt = f"""Téma: {topic}

Mások álláspontjai:
{chr(10).join(other_positions)}

Válaszolj az ellenérvekre és támaszd alá a saját álláspontodat."""

                response = await self.client.chat.completions.create(
                    model=participant.model_name,
                    messages=[{"role": "user", "content": counter_prompt}],
                    temperature=0.8,
                    max_tokens=800
                )

                counter_arg = response.choices[0].message.content
                participant.arguments.append(counter_arg)

                debate_log.append({
                    "round": round_num,
                    "model": participant.model_name,
                    "statement": counter_arg
                })

        judge_prompt = f"""Based on the debate log:
{json.dumps(debate_log, indent=2, ensure_ascii=False)}

Score each model from 0 to 1 on persuasiveness and return JSON:
{{
    "scores": {{
        "gptoss120b": 0.0,
        "llama3.370b": 0.0,
        "qwen332b": 0.0
    }}
}}"""

        judge_response = await self.client.chat.completions.create(
            model="gptoss120b",
            messages=[{"role": "user", "content": judge_prompt}],
            temperature=0.5,
            max_tokens=500
        )

        try:
            scores = json.loads(judge_response.choices[0].message.content).get("scores", {})
            for p in participants:
                p.confidence = scores.get(p.model_name, 0.8)
        except:
            pass

        synthesis_prompt = f"""Vita összefoglaló:
{json.dumps(debate_log, indent=2, ensure_ascii=False)}

Készíts egy szintézist amely azonosítja:
1. Közös pontokat
2. Legfontosabb nézeteltéréseket
3. Legjobb érveket
4. Végkövetkeztetést"""

        synthesis = await self.client.chat.completions.create(
            model="gptoss120b",
            messages=[{"role": "user", "content": synthesis_prompt}],
            temperature=0.6,
            max_tokens=1500
        )

        return {
            "topic": topic,
            "participants": [p.__dict__ for p in participants],
            "debate_log": debate_log,
            "synthesis": synthesis.choices[0].message.content,
            "winner": max(participants, key=lambda p: p.confidence).model_name
        }

class TemporalContextIntelligence:
    def __init__(self):
        self.interaction_history = []

    def analyze_temporal_patterns(self, user_id: str) > Dict[str, Any]:
        user_interactions = [i for i in self.interaction_history if i.get('user_id') == user_id]

        if not user_interactions:
            return {"patterns": [], "insights": "Nincs elég adat"}

        interactions_by_day = {}
        interactions_by_hour = {}

        for interaction in user_interactions:
            dt = datetime.fromisoformat(interaction['timestamp'])
            day = dt.strftime('%A')
            hour = dt.hour

            interactions_by_day[day] = interactions_by_day.get(day, 0) + 1
            interactions_by_hour[hour] = interactions_by_hour.get(hour, 0) + 1

        most_active_day = max(interactions_by_day.items(), key=lambda x: x[1])[0]
        most_active_hour = max(interactions_by_hour.items(), key=lambda x: x[1])[0]

        return {
            "total_interactions": len(user_interactions),
            "most_active_day": most_active_day,
            "most_active_hour": most_active_hour,
            "day_distribution": interactions_by_day,
            "hour_distribution": interactions_by_hour,
            "insights": f"Legtöbbször {most_active_day} napján, {most_active_hour} óra körül használod a rendszert."
        }

    def record_interaction(self, user_id: str, interaction_type: str, data: Dict):
        self.interaction_history.append({
            "user_id": user_id,
            "type": interaction_type,
            "data": data,
            "timestamp": datetime.now().isoformat()
        })

class AdaptivePersonalityMatrix:
