class SemanticTimeTravel:
    def __init__(self, supermemory_api_key: str):
        self.api_key = supermemory_api_key
        self.conversation_graph = {}

    async def build_semantic_graph(self, query: str = "") > Dict:
        data = await self._search_memories(query)
        conversations = data.get("results", [])
        graph = {
            "nodes": [],
            "edges": []
        }

        conv_dicts = []
        for conv in conversations:
            conv_dict = {
                "id": conv.get('id'),
                "messages": [{"content": conv.get('content', '')}],
                "created_at": conv.get('created_at')
            }
            conv_dicts.append(conv_dict)

            node = {
                "id": conv_dict.get('id'),
                "content": conv_dict.get('messages', []),
                "timestamp": conv_dict.get('created_at'),
                "topics": self._extract_topics(conv_dict)
            }
            graph["nodes"].append(node)

        for i, conv in enumerate(conv_dicts):
            for j, other_conv in enumerate(conv_dicts):
                if i != j:
                    similarity = self._calculate_semantic_similarity(
                        conv.get('messages', []),
                        other_conv.get('messages', [])
                    )
                    if similarity > 0.3:
                        graph["edges"].append({
                            "from": conv.get('id'),
                            "to": other_conv.get('id'),
                            "weight": similarity,
                            "reason": "semantic_similarity"
                        })

        return graph

    async def _search_memories(self, query: str) > Dict[str, Any]:
        async with aiohttp.ClientSession() as session:
            async with session.post(
                "",
                headers={
                    "Authorization": f"Bearer {self.api_key}",
                    "ContentType": "application/json"
                },
                json={"q": query}
            ) as resp:
                if resp.status == 200:
                    return await resp.json()
                else:
                    raise Exception(f"Supermemory API error: {resp.status}")

    def _extract_topics(self, conversation: Dict) > List[str]:
        messages = conversation.get('messages', [])
        text = " ".join([m.get('content', '') for m in messages])

        common_topics = ['AI', 'kód', 'programozás', 'adatbázis', 'API', 'frontend', 'backend']
        found_topics = [topic for topic in common_topics if topic.lower() in text.lower()]

        return found_topics if found_topics else ['általános']

    def _calculate_semantic_similarity(self, messages1: List, messages2: List) > float:
        text1 = " ".join([m.get('content', '') for m in messages1]).lower()
        text2 = " ".join([m.get('content', '') for m in messages2]).lower()

        words1 = set(text1.split())
        words2 = set(text2.split())

        if not words1 or not words2:
            return 0.0

        intersection = words1.intersection(words2)
        union = words1.union(words2)

        return len(intersection) / len(union) if union else 0.0

