class HallucinationDetector:
    def __init__(self, exa_api_key: str, cerebras_api_key: str):
        self.exa_key = exa_api_key
        self.cerebras_client = AsyncCerebras(api_key=cerebras_api_key)

    async def detect_and_correct(self, ai_response: str) > Dict[str, Any]:
        claims = self._extract_factual_claims(ai_response)

        verification_results = []
        for claim in claims:
            try:
                async with aiohttp.ClientSession() as session:
                    async with session.post(
                        "",
                        headers={"xapikey": self.exa_key, "ContentType": "application/json"},
                        json={
                            "query": claim,
                            "numResults": 3,
                            "type": "neural"
                        }
                    ) as exa_response:
                        if exa_response.status == 200:
                            data = await exa_response.json()
                            results = data.get('results', [])
                            verified = len(results) > 0
                        else:
                            verified = False
                            results = []

                        verification_results.append({
                            "claim": claim,
                            "verified": verified,
                            "sources": [r.get('url') for r in results]
                        })
            except Exception as e:
                verification_results.append({
                    "claim": claim,
                    "verified": False,
                    "error": str(e)
                })

        unverified_claims = [v for v in verification_results if not v['verified']]

        if unverified_claims:
            correction_prompt = f"""Ezek a következő állítások nem ellenőrizhetők:
{json.dumps(unverified_claims, indent=2, ensure_ascii=False)}

Eredeti válasz:
{ai_response}

Javítsd ki a választ úgy, hogy eltávolítod vagy módosítod az ellenőrizhetetlen állításokat."""

            corrected = await self.cerebras_client.chat.completions.create(
                model="gptoss120b",
                messages=[{"role": "user", "content": correction_prompt}],
                temperature=0.3,
                max_tokens=1500
            )

            corrected_response = corrected.choices[0].message.content
        else:
            corrected_response = ai_response

        return {
            "original": ai_response,
            "corrected": corrected_response,
            "verification_results": verification_results,
            "hallucination_detected": len(unverified_claims) > 0
        }

    def _extract_factual_claims(self, text: str) > List[str]:
        sentences = text.split('.')
        claims = [s.strip() for s in sentences if len(s.strip()) > 20 and any(c.isdigit() or c.isupper() for c in s)]
        return claims[:5]

class CognitiveLoadOptimizer:
    def optimize_response(self, response: str, user_reading_pattern: Dict) > str:
        avg_sentence_length = user_reading_pattern.get('avg_sentence_preference', 15)
        prefers_lists = user_reading_pattern.get('prefers_lists', True)
        max_paragraph_length = user_reading_pattern.get('max_paragraph', 3)

        sentences = [s.strip() for s in response.split('.') if s.strip()]

        optimized_paragraphs = []
        current_paragraph = []

        for sentence in sentences:
            words = sentence.split()

            if len(words) > avg_sentence_length  1.5:
                parts = []
                current_part = []
                for word in words:
                    current_part.append(word)
                    if len(current_part) >= avg_sentence_length:
                        parts.append(' '.join(current_part) + '.')
                        current_part = []
                if current_part:
                    parts.append(' '.join(current_part) + '.')
                current_paragraph.extend(parts)
            else:
                current_paragraph.append(sentence + '.')

            if len(current_paragraph) >= max_paragraph_length:
                optimized_paragraphs.append(' '.join(current_paragraph))
                current_paragraph = []

        if current_paragraph:
            optimized_paragraphs.append(' '.join(current_paragraph))

        if prefers_lists and len(optimized_paragraphs) > 2:
            formatted = "Összefoglaló:\n\n"
            for i, para in enumerate(optimized_paragraphs, 1):
                formatted += f"{i}. {para}\n\n"
            return formatted
        else:
            return '\n\n'.join(optimized_paragraphs)

class PredictiveContextLoader:
    def __init__(self):
        self.access_patterns = {}

    def predict_next_memories(self, current_query: str, user_id: str) > List[str]:
        user_patterns = self.access_patterns.get(user_id, [])

        if not user_patterns:
            return []

        query_words = set(current_query.lower().split())

        predictions = []
        for pattern in user_patterns:
            pattern_words = set(pattern.get('query', '').lower().split())
            union_set = query_words.union(pattern_words)
            similarity = len(query_words.intersection(pattern_words)) / len(union_set) if union_set else 0

            if similarity > 0.3:
                predictions.append({
                    "memory_id": pattern.get('memory_accessed'),
                    "confidence": similarity,
                    "reason": "past_access_pattern"
                })

        predictions.sort(key=lambda x: x['confidence'], reverse=True)
        return [pred["memory_id"] for pred in predictions[:5]]

    def record_access_pattern(self, user_id: str, query: str, memory_id: str):
        if user_id not in self.access_patterns:
            self.access_patterns[user_id] = []

        self.access_patterns[user_id].append({
            "query": query,
            "memory_accessed": memory_id,
            "timestamp": datetime.now().isoformat()
        })

        if len(self.access_patterns[user_id]) > 100:
            self.access_patterns[user_id] = self.access_patterns[user_id][100:]
